//! The font files the generators read: the IBM Plex fonts Ferman bundles (`app/assets/fonts/`,
//! pinned in `tools/fonts/fonts.lock`) and the fonts `tools/corpus/fetch-fonts.sh` downloads into
//! `build/corpus-fonts/` (pinned in `tools/corpus/fonts.lock`). Every file is checked against its
//! pinned SHA-256 before a generator uses it, so the generated bytes depend only on this
//! repository.

use crate::sha256_hex;
use std::fs;
use std::path::{Path, PathBuf};

/// A font a generator embeds or draws.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum FontFile {
    /// IBM Plex Serif Regular, the body text of the Turkish documents.
    PlexSerif,
    /// IBM Plex Serif Italic.
    PlexSerifItalic,
    /// IBM Plex Serif SemiBold, the headings.
    PlexSerifSemiBold,
    /// IBM Plex Sans Regular.
    PlexSans,
    /// IBM Plex Sans Medium.
    PlexSansMedium,
    /// IBM Plex Sans SemiBold.
    PlexSansSemiBold,
    /// IBM Plex Mono Regular.
    PlexMono,
    /// EB Garamond, a variable font used at its default (Regular) instance. Fetched.
    EbGaramond,
}

/// Where a font file lives and which lock pins it.
enum Origin {
    /// `app/assets/fonts/ibm-<package>/<file>`, pinned by `tools/fonts/fonts.lock`.
    Bundled {
        package: &'static str,
        file: &'static str,
    },
    /// `build/corpus-fonts/<file>`, pinned by `tools/corpus/fonts.lock`.
    Fetched { file: &'static str },
}

impl FontFile {
    fn origin(self) -> Origin {
        let bundled = |package, file| Origin::Bundled { package, file };
        match self {
            Self::PlexSerif => bundled("plex-serif", "IBMPlexSerif-Regular.ttf"),
            Self::PlexSerifItalic => bundled("plex-serif", "IBMPlexSerif-Italic.ttf"),
            Self::PlexSerifSemiBold => bundled("plex-serif", "IBMPlexSerif-SemiBold.ttf"),
            Self::PlexSans => bundled("plex-sans", "IBMPlexSans-Regular.ttf"),
            Self::PlexSansMedium => bundled("plex-sans", "IBMPlexSans-Medium.ttf"),
            Self::PlexSansSemiBold => bundled("plex-sans", "IBMPlexSans-SemiBold.ttf"),
            Self::PlexMono => bundled("plex-mono", "IBMPlexMono-Regular.ttf"),
            Self::EbGaramond => Origin::Fetched {
                file: "EBGaramond-VF.ttf",
            },
        }
    }
}

/// What the generators read, relative to a repository root.
#[derive(Debug, Clone)]
pub struct Sources {
    root: PathBuf,
}

impl Sources {
    /// The sources of the checkout at `root`.
    #[must_use]
    pub fn new(root: &Path) -> Self {
        Self {
            root: root.to_path_buf(),
        }
    }

    /// The bytes of `font`, checked against its pinned SHA-256.
    ///
    /// # Errors
    ///
    /// A message when the file or its lock cannot be read, the lock does not pin it, or its
    /// SHA-256 differs. A fetched font that is missing names `tools/corpus/fetch-fonts.sh`.
    pub fn font(&self, font: FontFile) -> Result<Vec<u8>, String> {
        let (path, lock, key) = match font.origin() {
            Origin::Bundled { package, file } => (
                self.root
                    .join("app/assets/fonts")
                    .join(format!("ibm-{package}"))
                    .join(file),
                "tools/fonts/fonts.lock",
                format!("font {package} {file} "),
            ),
            Origin::Fetched { file } => (
                self.root.join("build/corpus-fonts").join(file),
                "tools/corpus/fonts.lock",
                format!("file {file} "),
            ),
        };
        let lock_text =
            fs::read_to_string(self.root.join(lock)).map_err(|err| format!("{lock}: {err}"))?;
        let pinned = lock_text
            .lines()
            .map(|line| line.split_whitespace().collect::<Vec<_>>().join(" "))
            .find_map(|line| {
                line.strip_prefix(&key)
                    .and_then(|rest| rest.split(' ').next())
                    .map(str::to_owned)
            })
            .ok_or_else(|| format!("{lock} does not pin {}", path.display()))?;
        let bytes = fs::read(&path).map_err(|err| {
            if matches!(font.origin(), Origin::Fetched { .. }) {
                format!(
                    "{}: {err}; run tools/corpus/fetch-fonts.sh first",
                    path.display()
                )
            } else {
                format!("{}: {err}", path.display())
            }
        })?;
        let actual = sha256_hex(&bytes);
        if actual != pinned {
            return Err(format!(
                "{}: SHA-256 {actual}, but {lock} pins {pinned}",
                path.display()
            ));
        }
        Ok(bytes)
    }
}
